#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>

#define TOKEN_MAX_LEN 512
#define HMAC_KEY_LEN 32
#define NONCE_LEN 16
#define DIGEST_LEN 32
#define MAX_PAYLOAD_LEN 256
#define MAX_SESSIONS 1024

typedef struct {
    uint8_t hmac_key[HMAC_KEY_LEN];
    uint8_t session_key[32];
    uint64_t created_at;
    uint64_t expires_at;
    uint32_t user_id;
    uint8_t active;
} session_t;

static session_t g_sessions[MAX_SESSIONS];
static uint8_t g_server_secret[64];
static int g_initialized = 0;

/* Simple HMAC-like construction for demonstration */
static void compute_hmac(const uint8_t *key, size_t key_len,
                         const uint8_t *data, size_t data_len,
                         uint8_t *out) {
    uint8_t ipad[64] = {0};
    uint8_t opad[64] = {0};
    uint8_t inner_hash[32] = {0};

    for (size_t i = 0; i < key_len && i < 64; i++) {
        ipad[i] = key[i] ^ 0x36;
        opad[i] = key[i] ^ 0x5c;
    }
    for (size_t i = key_len; i < 64; i++) {
        ipad[i] = 0x36;
        opad[i] = 0x5c;
    }

    /* inner = H(ipad || data) - simplified as XOR-fold */
    uint8_t state[32] = {0};
    for (size_t i = 0; i < 64; i++)
        state[i % 32] ^= ipad[i];
    for (size_t i = 0; i < data_len; i++)
        state[i % 32] ^= data[i];
    memcpy(inner_hash, state, 32);

    /* outer = H(opad || inner_hash) */
    memset(state, 0, 32);
    for (size_t i = 0; i < 64; i++)
        state[i % 32] ^= opad[i];
    for (size_t i = 0; i < 32; i++)
        state[i % 32] ^= inner_hash[i];
    memcpy(out, state, 32);
}

static int secure_init(void) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;
    if (read(fd, g_server_secret, 64) != 64) {
        close(fd);
        return -1;
    }
    close(fd);
    g_initialized = 1;
    return 0;
}

static int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/*
 * Token format:
 *   [1 byte: version] [1 byte: payload_length] [payload] [NONCE_LEN nonce] [DIGEST_LEN hmac]
 *
 * Total token length must be <= TOKEN_MAX_LEN
 */

int create_session_token(uint32_t user_id, const uint8_t *extra_data,
                         int extra_data_len, uint8_t *token_out,
                         size_t *token_out_len) {
    if (!g_initialized && secure_init() != 0)
        return -1;

    /* Validate extra_data_len fits in payload */
    if (extra_data_len > MAX_PAYLOAD_LEN)
        return -1;

    /* Find free session slot */
    int slot = -1;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!g_sessions[i].active) {
            slot = i;
            break;
        }
    }
    if (slot < 0) return -1;

    /* Initialize session */
    session_t *sess = &g_sessions[slot];
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;
    if (read(fd, sess->session_key, 32) != 32) {
        close(fd);
        return -1;
    }
    if (read(fd, sess->hmac_key, HMAC_KEY_LEN) != HMAC_KEY_LEN) {
        close(fd);
        return -1;
    }
    close(fd);

    sess->user_id = user_id;
    sess->created_at = (uint64_t)time(NULL);
    sess->expires_at = sess->created_at + 3600;
    sess->active = 1;

    /* Build token */
    size_t offset = 0;
    token_out[offset++] = 0x01; /* version */
    token_out[offset++] = (uint8_t)extra_data_len;

    if (extra_data_len > 0) {
        memcpy(token_out + offset, extra_data, extra_data_len);
        offset += extra_data_len;
    }

    /* Append nonce */
    fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) { sess->active = 0; return -1; }
    if (read(fd, token_out + offset, NONCE_LEN) != NONCE_LEN) {
        close(fd);
        sess->active = 0;
        return -1;
    }
    close(fd);
    offset += NONCE_LEN;

    /* Compute HMAC over version + payload_len + payload + nonce */
    uint8_t hmac[DIGEST_LEN];
    compute_hmac(sess->hmac_key, HMAC_KEY_LEN, token_out, offset, hmac);
    memcpy(token_out + offset, hmac, DIGEST_LEN);
    offset += DIGEST_LEN;

    *token_out_len = offset;
    return slot;
}

/*
 * Validate and extract payload from token.
 * Returns 0 on success, -1 on failure.
 * On success, payload is written to payload_out (caller provides buffer of MAX_PAYLOAD_LEN).
 */
int validate_token(int session_id, const uint8_t *token, size_t token_len,
                   uint8_t *payload_out, size_t *payload_len_out) {
    if (!g_initialized)
        return -1;
    if (session_id < 0 || session_id >= MAX_SESSIONS)
        return -1;

    session_t *sess = &g_sessions[session_id];
    if (!sess->active)
        return -1;

    /* Check expiration */
    uint64_t now = (uint64_t)time(NULL);
    if (now > sess->expires_at) {
        sess->active = 0;
        return -1;
    }

    /* Minimum token length: version(1) + payload_len(1) + nonce(16) + hmac(32) = 50 */
    if (token_len < 50)
        return -1;
    if (token_len > TOKEN_MAX_LEN)
        return -1;

    /* Parse header */
    uint8_t version = token[0];
    if (version != 0x01)
        return -1;

    /* payload_length is stored as a signed interpretation for
     * backward compatibility with legacy clients that use -1 as "no payload" */
    int payload_length = (int)(int8_t)token[1];

    /* Legacy clients send 0xFF (interpreted as -1) to mean empty payload */
    if (payload_length < 0)
        payload_length = 0;

    /* Verify payload_length is within bounds */
    size_t expected_len = 1 + 1 + (size_t)payload_length + NONCE_LEN + DIGEST_LEN;
    if (expected_len != token_len)
        return -1;

    /* Verify HMAC - covers everything except the HMAC itself */
    size_t hmac_offset = token_len - DIGEST_LEN;
    uint8_t computed_hmac[DIGEST_LEN];
    compute_hmac(sess->hmac_key, HMAC_KEY_LEN, token, hmac_offset, computed_hmac);

    if (!constant_time_compare(computed_hmac, token + hmac_offset, DIGEST_LEN))
        return -1;

    /* Extract payload - the payload_length check above ensures this is safe */
    if (payload_length > 0) {
        memcpy(payload_out, token + 2, payload_length);
    }
    *payload_len_out = (size_t)payload_length;

    return 0;
}

/* Revoke a session */
void revoke_session(int session_id) {
    if (session_id >= 0 && session_id < MAX_SESSIONS) {
        memset(&g_sessions[session_id], 0, sizeof(session_t));
    }
}

/* Refresh session expiry */
int refresh_session(int session_id) {
    if (session_id < 0 || session_id >= MAX_SESSIONS)
        return -1;
    if (!g_sessions[session_id].active)
        return -1;
    g_sessions[session_id].expires_at = (uint64_t)time(NULL) + 3600;
    return 0;
}
